void layout_sizes_json(std::ostream& o){o<<'{';o<<"\"guardResult\":"<<sizeof(g::GuardResult);o<<',';o<<"\"bodyRecord\":"<<sizeof(g::BodyRecord);o<<',';o<<"\"rigidBody\":"<<sizeof(dynamics::RigidBody);o<<',';o<<"\"plane\":"<<sizeof(dynamics::Plane);o<<',';o<<"\"staticMeshSource\":"<<sizeof(g::StaticMeshSource);o<<',';o<<"\"pairRecord\":"<<sizeof(g::PairRecord);o<<',';o<<"\"preparationPair\":"<<sizeof(preparation::Pair);o<<',';o<<"\"staticTriangle\":"<<sizeof(pikapika::sphere_triangle::StaticTriangle);o<<',';o<<"\"heldAudit\":"<<sizeof(pikapika::sphere_triangle_mesh_held_load::CellAudit);o<<',';o<<"\"heldCertifiedLeaf\":"<<sizeof(pikapika::sphere_triangle_mesh_held_load::CertifiedLeaf);o<<',';o<<"\"heldPartitionLeaf\":"<<sizeof(pikapika::sphere_triangle_mesh_held_load::PartitionLeaf);o<<',';o<<"\"heldCell\":"<<sizeof(pikapika::sphere_triangle_mesh_held_load::Cell);o<<',';o<<"\"meshRow\":"<<sizeof(pikapika::sphere_triangle_mesh::Row);o<<',';o<<"\"uint64\":"<<sizeof(std::uint64_t);o<<',';o<<"\"primitiveCandidateAudit\":"<<sizeof(pikapika::sphere_triangle::CandidateAudit);o<<',';o<<"\"metricAudit\":"<<sizeof(pikapika::accelerated_pair_coverage::Audit);o<<',';o<<"\"metricPartitionLeaf\":"<<sizeof(pikapika::accelerated_pair_coverage::PartitionLeaf);o<<',';o<<"\"metricCell\":"<<sizeof(pikapika::accelerated_pair_coverage::Cell);o<<',';o<<"\"planeBoxAudit\":"<<sizeof(pikapika::accelerated_plane_box_coverage::Audit);o<<',';o<<"\"planeBoxPartitionLeaf\":"<<sizeof(pikapika::accelerated_plane_box_coverage::PartitionLeaf);o<<',';o<<"\"planeBoxCell\":"<<sizeof(pikapika::accelerated_plane_box_coverage::Cell);o<<',';o<<"\"sphereBoxAudit\":"<<sizeof(pikapika::accelerated_sphere_box_coverage::Audit);o<<',';o<<"\"sphereBoxPartitionLeaf\":"<<sizeof(pikapika::accelerated_sphere_box_coverage::PartitionLeaf);o<<',';o<<"\"sphereBoxCell\":"<<sizeof(pikapika::accelerated_sphere_box_coverage::Cell);o<<'}';}
void emit_fixtures(std::ostream& o,const std::vector<Case>& corpus){if(g::current_binding().state!=g::BindingState::ready){throw std::runtime_error("Full finite corpus requires an audited supported profile; no fabricated binding fill");}o<<"{\"schema\":1,\"kind\":\"world-static-mesh-flight-guard-fixtures\",\"layoutSizes\":";layout_sizes_json(o);o<<",\"fixtures\":[";for(std::size_t i=0;i<corpus.size();++i){if(i){o<<',';}const auto& x=corpus[i];o<<"{\"name\":\""<<x.name<<"\",\"input\":";input_json(o,x);o<<",\"result\":";result_json(o,g::query(x.world,x.meshes,x.horizon,x.settings));o<<'}';}o<<"]}\n";}
